const document = $input.first().json.text;

if (typeof document !== 'string' || !document.trim()) {
  throw new Error('Knowledge document is empty or invalid.');
}

// Split by Markdown level-2 heading markers
// Supports both multiline and flattened text
const sections = document
  .split(/(?<!#)##[ \t]+/)
  .slice(1)
  .map(section => section.trim())
  .filter(Boolean);

if (sections.length === 0) {
  throw new Error('No knowledge sections found.');
}

// Extract uppercase section headings and content
return sections.map((section, index) => {
  const match = section.match(
    /^([A-Z][A-Z0-9 &/(),'-]*?)(?=\s{2,}|\r?\n)/
  );

  if (!match) {
    throw new Error(
      `Unable to identify heading in section ${index + 1}`
    );
  }

  const title = match[1].trim();
  const content = section.slice(match[0].length).trim();

  if (!content) {
    throw new Error(`Empty content in section: ${title}`);
  }

  return {
    json: {
      section_id: `KB-${String(index + 1).padStart(3, '0')}`,
      section_title: title,
      text: `${title}\n\n${content}`,
      source: 'Range Explorer Outdoor Knowledge Base',
      document_version: '1.1'
    }
  };
});
